import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const lista=v=>Array.isArray(v)?v:v==null?[]:[v];
function valores(item,chave){const m=item?.metadata;if(Array.isArray(m))return m.filter(x=>x?.key===chave||String(x?.key||'').startsWith(chave+'.')).map(x=>x?.value).filter(Boolean).map(String);if(m&&typeof m==='object'){const v=m[chave];return lista(v).map(x=>typeof x==='object'?(x.value??x.display??''):x).filter(Boolean).map(String)}return[]}
function itensResposta(d){if(Array.isArray(d))return d;if(Array.isArray(d?.items))return d.items;if(Array.isArray(d?.results))return d.results;if(Array.isArray(d?._embedded?.items))return d._embedded.items;return[]}
function formatos(item,base){const saida=[];for(const b of lista(item?.bitstreams)){const nome=String(b?.name||''),mime=String(b?.mimeType||b?.format||b?.description||''),tipo=/\.epub$/i.test(nome)||/epub/i.test(mime)?'EPUB':/\.pdf$/i.test(nome)||/pdf/i.test(mime)?'PDF':null;if(!tipo)continue;let url=endereco(b?.retrieveLink)||null;if(!url&&b?.retrieveLink)try{url=new URL(b.retrieveLink,base).href}catch{}if(!url&&b?.uuid)url=`${base}/rest/bitstreams/${encodeURIComponent(b.uuid)}/retrieve`;if(url&&!saida.some(x=>x.tipo===tipo&&x.url===url))saida.push({tipo,url})}return saida}
function converter(item,fonte){const base=fonte==='oapen'?'https://library.oapen.org':'https://directory.doabooks.org',provedor=fonte==='oapen'?'OAPEN Library':'DOAB · Open Access Books',handle=String(item?.handle||'').trim(),id=String(item?.uuid||handle||item?.id||'').trim();if(!id)return null;const titulo=valores(item,'dc.title')[0]||item?.name||'Sem título',autores=[...valores(item,'dc.contributor.author'),...valores(item,'dc.creator')],langs=idiomas([...valores(item,'dc.language.iso'),...valores(item,'dc.language')]),descricao=valores(item,'dc.description.abstract')[0]||valores(item,'dc.description')[0]||'',ler=endereco(handle?`${base}/handle/${handle}`:item?.link)||endereco(item?.link)||base,arquivos=formatos(item,base),capa=arquivos.find(x=>/image/i.test(x.tipo||''))?.url||null;return{id:`${fonte}:${id}`,fonte,provedor,titulo:String(titulo),autores:[...new Set(autores)],idiomas:langs,capa,descricao,acessoLivre:true,dominioPublico:false,tipoAcesso:arquivos.length?'Livro acadêmico aberto · arquivo':'Livro acadêmico aberto',licenca:`Obra de acesso aberto indexada pelo ${provedor}. A licença específica é indicada no registro da obra.`,origem:ler,ler,texto:null,formatos:arquivos.slice(0,3)}}
async function pesquisar(fonte,q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte',fonte);u.searchParams.set('q',o.resgate?`dc.title:"${termo.replace(/"/g,' ')}"`:termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,14000,2),itens=itensResposta(d),livros=itens.map(x=>converter(x,fonte)).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const total=Number(d?.total||d?.totalElements||d?.page?.totalElements)||livros.length,temMais=Number.isFinite(total)&&total>livros.length?pagina*20<total:itens.length>=20;return{livros,total,temMais}}
export const pesquisarOapen=(q,o)=>pesquisar('oapen',q,o);
export const pesquisarDoab=(q,o)=>pesquisar('doab',q,o);
